import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;

import org.springframework.stereotype.Service;

/**
 * Keeps every message sent through the contact form, in memory, for the
 * lifetime of the application.
 */
@Service
public class ContactMessageService {

    private final Deque<ContactMessage> messages = new ArrayDeque<>();

    public synchronized void add(ContactMessage message) {
        messages.addFirst(message);
    }

    /**
     * @return a snapshot of all sent messages, newest first
     */
    public synchronized List<ContactMessage> findAllNewestFirst() {
        return List.copyOf(messages);
    }
}
