+package com.example.contact;
+
+import java.util.List;
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    // Deliberately simple: one @, no spaces, a dot in the domain part.
+    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final ContactMessageService messageService;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    /** True while the form is being cleared after a send, so that clearing does not re-enable Send. */
+    private boolean clearing;
+
+    public ContactView(ContactMessageService messageService) {
+        this.messageService = messageService;
+
+        setupFields();
+        setupGrid();
+        setupLeaveDialog();
+
+        sendButton.addClickListener(event -> send());
+        Shortcuts.addShortcutListener(this, this::send, Key.ENTER);
+
+        add(
+                new H1("Contact"),
+                new RouterLink("About", AboutView.class),
+                new FormLayout(nameField, emailField, phoneField, messageField),
+                sendButton,
+                grid);
+        refreshGrid();
+    }
+
+    private void setupFields() {
+        // Eager, so that Enter sends what was typed and every keystroke counts as an edit.
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        for (var field : List.of(nameField, emailField, phoneField, messageField)) {
+            field.addValueChangeListener(event -> {
+                if (!clearing) {
+                    sendButton.setEnabled(true);
+                }
+            });
+        }
+    }
+
+    private void setupGrid() {
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("E-mail");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setAutoWidth(true);
+    }
+
+    private void setupLeaveDialog() {
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.setCloseOnEsc(false);
+        leaveDialog.setCloseOnOutsideClick(false);
+        leaveDialog.add(new Paragraph("The form has text in it. Leaving now will throw it away."));
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            leaveDialog.close();
+            if (pendingNavigation != null) {
+                pendingNavigation.cancel();
+                pendingNavigation = null;
+            }
+        });
+        Button discard = new Button("Discard", event -> {
+            leaveDialog.close();
+            if (pendingNavigation != null) {
+                pendingNavigation.proceed();
+                pendingNavigation = null;
+            }
+        });
+        leaveDialog.getFooter().add(new HorizontalLayout(keepEditing, discard));
+
+        add(leaveDialog);
+    }
+
+    private void send() {
+        if (!sendButton.isEnabled() || !validate()) {
+            return;
+        }
+
+        messageService.add(new ContactMessage(
+                nameField.getValue().strip(),
+                emailField.getValue().strip(),
+                phoneField.getValue().strip(),
+                messageField.getValue().strip()));
+
+        Notification.show("Message sent");
+
+        clearing = true;
+        try {
+            nameField.clear();
+            emailField.clear();
+            phoneField.clear();
+            messageField.clear();
+        } finally {
+            clearing = false;
+        }
+        sendButton.setEnabled(false);
+        refreshGrid();
+    }
+
+    /**
+     * Marks every failing field invalid with its error message, clears the
+     * marking from the others.
+     *
+     * @return true if the form may be sent
+     */
+    private boolean validate() {
+        String name = nameField.getValue().strip();
+        String email = emailField.getValue().strip();
+        String phone = phoneField.getValue().strip();
+        String message = messageField.getValue().strip();
+
+        String nameError = name.isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (!email.isEmpty() && !EMAIL.matcher(email).matches()) {
+            emailError = "Enter a valid e-mail address";
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+
+        String messageError = null;
+        if (message.isEmpty()) {
+            messageError = "Message is required";
+        } else if (message.codePointCount(0, message.length()) > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+
+        mark(nameField, nameError);
+        mark(emailField, emailError);
+        mark(messageField, messageError);
+
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private static void mark(HasValidation field, String error) {
+        field.setInvalid(error != null);
+        if (error != null) {
+            field.setErrorMessage(error);
+        }
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.findAllNewestFirst());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsentInput()) {
+            return;
+        }
+        pendingNavigation = event.postpone();
+        leaveDialog.open();
+    }
+
+    private boolean hasUnsentInput() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+    }
+}
