+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return $(TextField.class).withCaption("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withCaption("Phone").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        name().setValue(name);
+        email().setValue(email);
+        phone().setValue(phone);
+        message().setValue(message);
+    }
+
+    @Test
+    void emptyFormHasEnabledSendAndEmptyFields() {
+        navigate(ContactView.class);
+
+        assertTrue(send().isEnabled());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void emptyFormReportsEveryRequiredField() {
+        navigate(ContactView.class);
+
+        send().click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void invalidEmailIsReported() {
+        navigate(ContactView.class);
+        fill("Ada", "not-an-address", "", "Hello");
+
+        send().click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void tooLongMessageIsReported() {
+        navigate(ContactView.class);
+        fill("Ada", "", "123", "x".repeat(501));
+
+        send().click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneIsEnoughAndSendsMessage() {
+        navigate(ContactView.class);
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        int notificationsBefore = notificationsWithText("Message sent").size();
+        int rowsBefore = grid.getListDataView().getItemCount();
+
+        fill("Ada", "", "+358 40 123", "Hello");
+        send().click();
+
+        assertFalse(email().isInvalid());
+        assertEquals("", name().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+        assertEquals(notificationsBefore + 1, notificationsWithText("Message sent").size());
+        assertEquals(rowsBefore + 1, grid.getListDataView().getItemCount());
+        assertEquals("Ada", grid.getListDataView().getItems().findFirst().orElseThrow().name());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        fill("Grace", "grace@example.com", "", "Hi there");
+
+        fireShortcut(Key.ENTER);
+
+        assertFalse(send().isEnabled());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void editingAfterSendReenablesSend() {
+        navigate(ContactView.class);
+        fill("Grace", "grace@example.com", "", "Hi there");
+        send().click();
+        assertFalse(send().isEnabled());
+
+        name().setValue("G");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void sentMessagesStayNewestFirstAcrossVisits() {
+        navigate(ContactView.class);
+        fill("First Sender", "", "111", "first");
+        send().click();
+        fill("Second Sender", "", "222", "second");
+        send().click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        var items = grid.getListDataView().getItems().toList();
+        assertEquals("Second Sender", items.get(0).name());
+        assertEquals("First Sender", items.get(1).name());
+    }
+
+    @Test
+    void leavingWithEmptyFormIsNotInterrupted() {
+        navigate(ContactView.class);
+
+        leaveTo(AboutView.class);
+
+        assertNotNull($(AboutView.class).single());
+        assertFalse($(Dialog.class).exists());
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStaysOnView() {
+        navigate(ContactView.class);
+        name().setValue("Ada");
+
+        leaveTo(AboutView.class);
+
+        assertFalse($(AboutView.class).exists());
+        assertNotNull($(ContactView.class).single());
+        assertTrue($(Dialog.class).single().isOpened());
